code.cpp:
class Solution {
public:
    int commonFactors(int a, int b) {
        int g = gcd(a, b);
        int count = 0;
        for (int i = 1; i * i <= g; ++i) {
            if (g % i == 0) {
                if (i * i == g) {
                    count += 1;
                } else {
                    count += 2;
                }
            }
        }
        return count;
    }

private:
    int gcd(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
};
